var sb = new System.Text.StringBuilder();
var searches = UnityEngine.Object.FindObjectsByType<RaySearch>(FindObjectsInactive.Include, FindObjectsSortMode.None);
foreach (var s in searches)
{
    var parent = s.transform.parent;
    Vector3 origin = s.transform.position + Vector3.up * 0.5f;
    Vector3 dir;
    if (parent != null)
    {
        dir = (parent.position - origin); dir.y = 0; dir.Normalize();
        if (dir.sqrMagnitude < 0.001f) dir = s.transform.forward;
    }
    else dir = s.transform.forward;
    s.mergeMode = WallMerge.WallMergeMode.Current;
    s.DoPointsFromPlayer(origin, dir);
    string parentName = parent != null ? parent.name : s.gameObject.name;
    int N = s.cornerPoints.Count;
    sb.AppendLine($"=== {parentName}: cornerPoints={N}, IsClosedLoop={s.IsClosedLoop} ===");
    if (N == 0) continue;
    float distanceToTurn = 1f;
    int badCount = 0;
    float maxDist = 0f;
    for (int i = 0; i < N; i++)
    {
        Vector3 cur = s.cornerPoints[i].position;
        int prev = s.IsClosedLoop ? (i - 1 + N) % N : Mathf.Max(i - 1, 0);
        int next = s.IsClosedLoop ? (i + 1) % N : Mathf.Min(i + 1, N - 1);
        // Simulate: came from previous corner, going right (to next)
        Vector3 nFrom = s.cornerPoints[prev].normal;
        Vector3 nTo = s.cornerPoints[next].normal;
        Vector3 outward = (nFrom + nTo);
        Vector3 inward = (outward.sqrMagnitude < 0.0001f) ? -nFrom : -outward.normalized;
        Vector3 pivot = cur + inward * distanceToTurn;
        float distFromCorner = Vector3.Distance(pivot, cur);
        if (distFromCorner > 5f || float.IsNaN(pivot.x)) badCount++;
        if (distFromCorner > maxDist) maxDist = distFromCorner;
    }
    sb.AppendLine($"  pivots: bad={badCount}/{N}, maxDistFromCorner={maxDist:F2}m (target ~{distanceToTurn:F2}m)");
}
return sb.ToString();
